// Generates the mockup sprite ui/mockups/icons.svg and src/lib/components/ui/icons.ts from the
// Lucide icons in the `lucide-static` package (ISC licence, see packaging/UI_THIRD_PARTY_NOTICES).
//
// The app draws each icon as inline SVG elements, so it needs no sprite request and no
// `<use>` reference under the strict policy (ADR-0027). The test Icon.test.ts fails
// when the generated file and the sprite differ.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { parseSprite } from './sprite.mjs';

/** App icon name -> Lucide icon file name. */
export const mapping = {
	overview: 'layout-grid',
	host: 'monitor',
	job: 'circle-play',
	clock: 'clock',
	repository: 'database',
	profile: 'layers',
	restore: 'history',
	audit: 'scroll-text',
	settings: 'settings',
	search: 'search',
	bell: 'bell',
	'chevron-down': 'chevron-down',
	'chevron-up': 'chevron-up',
	'chevron-right': 'chevron-right',
	'chevron-left': 'chevron-left',
	'arrow-right': 'arrow-right',
	'arrow-left': 'arrow-left',
	check: 'check',
	x: 'x',
	alert: 'triangle-alert',
	info: 'info',
	octagon: 'octagon-alert',
	'check-circle': 'circle-check',
	'x-circle': 'circle-x',
	user: 'user',
	users: 'users',
	plus: 'plus',
	filter: 'funnel',
	copy: 'copy',
	more: 'ellipsis',
	sun: 'sun',
	moon: 'moon',
	refresh: 'refresh-cw',
	download: 'download',
	upload: 'upload',
	trash: 'trash-2',
	sort: 'arrow-up-down',
	terminal: 'terminal',
	file: 'file',
	folder: 'folder',
	key: 'key-round',
	mail: 'mail',
	shield: 'shield',
	external: 'external-link',
	lock: 'lock',
	eye: 'eye',
	'eye-off': 'eye-off',
	calendar: 'calendar',
	dot: 'circle-small',
	stop: 'square',
	pause: 'pause',
	'loader-circle': 'loader-circle',
	'circle-slash': 'circle-slash',
	cloud: 'cloud',
	activity: 'activity',
	tag: 'tag',
	box: 'box',
	book: 'book-open',
	grip: 'grip-vertical',
	checklist: 'list-checks',
	flask: 'flask-conical',
	'folder-open': 'folder-open',
	link: 'link',
	'file-text': 'file-text',
	'file-code': 'file-code',
	'file-image': 'file-image',
	'file-audio': 'file-audio',
	'file-video': 'file-video',
	'file-archive': 'file-archive',
	'file-spreadsheet': 'file-spreadsheet',
	'file-document': 'file-type',
	'file-executable': 'file-terminal',
	'file-other': 'file-question-mark',
	'monitor-off': 'monitor-off',
	'monitor-x': 'monitor-x',
	hourglass: 'hourglass',
	'calendar-check': 'calendar-check',
	'calendar-clock': 'calendar-clock',
	'calendar-x': 'calendar-x',
	'calendar-off': 'calendar-off',
	'database-zap': 'database-zap',
	'lock-keyhole': 'lock-keyhole',
	'bell-off': 'bell-off',
	'user-x': 'user-x',
	'building-2': 'building-2',
	ticket: 'ticket',
	'clock-alert': 'clock-alert',
	'octagon-x': 'octagon-x',
	'send-horizontal': 'send-horizontal',
	send: 'send',
	'list-ordered': 'list-ordered',
	'square-terminal': 'square-terminal',
	camera: 'camera',
	'circle-stop': 'circle-stop',
	power: 'power',
	ban: 'ban',
	replace: 'replace',
	play: 'play',
	webhook: 'webhook',
	eraser: 'eraser',
	'shield-check': 'shield-check',
	'plug-zap': 'plug-zap',
	'rotate-ccw': 'rotate-ccw'
};

/** Icons that Lucide draws as an outline but the app shows as a solid shape. */
const filled = new Set(['dot']);

const lucide = fileURLToPath(new URL('../node_modules/lucide-static/icons/', import.meta.url));
const sprite = fileURLToPath(new URL('../mockups/icons.svg', import.meta.url));
const target = fileURLToPath(new URL('../src/lib/components/ui/icons.ts', import.meta.url));

const version = JSON.parse(
	readFileSync(new URL('../node_modules/lucide-static/package.json', import.meta.url), 'utf8')
).version;

const symbols = Object.entries(mapping).map(([name, file]) => {
	const source = readFileSync(`${lucide}${file}.svg`, 'utf8');
	const inner = source.replace(/^[\s\S]*?<svg\b[^>]*>/, '').replace(/<\/svg>[\s\S]*$/, '');
	const shapes = [
		...inner.matchAll(/<(?:path|circle|rect|ellipse|line|polyline|polygon)\b[^>]*?\/>/g)
	]
		.map((shape) => shape[0].replace(/\s+/g, ' ').replace(/\s*\/>$/, ' />'))
		.map((shape) => (filled.has(name) ? shape.replace(/ \/>$/, ' fill="currentColor" />') : shape));
	if (shapes.length === 0) throw new Error(`Lucide icon ${file} has no shapes`);
	return `\t<symbol id="i-${name}" viewBox="0 0 24 24">\n${shapes.map((shape) => `\t\t${shape}`).join('\n')}\n\t</symbol>`;
});

writeFileSync(
	sprite,
	`<svg xmlns="http://www.w3.org/2000/svg" style="display: none">
	<!--
		Generated by scripts/gen-icons.mjs from Lucide v${version} (ISC licence). Do not edit.
		Every symbol draws with the current text color on a 24px grid; mockups.css sets a 2 stroke.
		Load a symbol with: <svg class="icon"><use href="icons.svg#i-host"/></svg>
	-->
${symbols.join('\n')}
</svg>
`
);

const icons = parseSprite(readFileSync(sprite, 'utf8'));
const body = Object.entries(icons)
	.map(([name, shapes]) => `\t${JSON.stringify(name)}: ${JSON.stringify(shapes)}`)
	.join(',\n');

writeFileSync(
	target,
	`// Generated by scripts/gen-icons.mjs from ui/mockups/icons.svg. Do not edit.

export type IconShape = [
	'path' | 'circle' | 'rect' | 'ellipse' | 'line' | 'polyline' | 'polygon',
	Record<string, string>
];

export const icons = {
${body}
} satisfies Record<string, IconShape[]>;

export type IconName = keyof typeof icons;
`
);
